python3 - <<'PYEOF'
import json

end_def = json.load(open('/tmp/end_def_clean.json'))
tr_def = json.load(open('/tmp/tr_def_clean.json'))

catalog = [
  {"title": "Linear Algebra Done Right", "author": "Axler", "field": "math", "difficulty": 6, "pages": 340},
  {"title": "Deep Learning", "author": "Goodfellow", "field": "ml", "difficulty": 9, "pages": 800},
  {"title": "Statistical Learning", "author": "James", "field": "data science", "difficulty": 4, "pages": 440},
  {"title": "Elements of Statistical Learning", "author": "Hastie", "field": "stats", "difficulty": 9, "pages": 745},
  {"title": "Bayesian Data Analysis", "author": "Gelman", "field": "stats", "difficulty": 8, "pages": 580},
  {"title": "Python for Data Analysis", "author": "McKinney", "field": "data science", "difficulty": 3, "pages": 550},
  {"title": "Probability Theory", "author": "Jaynes", "field": "math", "difficulty": 10, "pages": 753},
  {"title": "Information Theory", "author": "MacKay", "field": "ml", "difficulty": 7, "pages": 540}
]

flow = {
  "id": "9ef8755f-8fb3-48ad-b891-af0684a0a720",
  "version": "1.8",
  "name": "ReadingList",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {"label": "Manual trigger"},
      "inputs": {
        "entryPointId": "067b1bba-c6fc-428a-95e3-915c12128d9a",
        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "transformChain",
      "type": "core.action.transform",
      "typeVersion": "1.0",
      "display": {"label": "Curate Reading List"},
      "inputs": {
        "collection": "$vars.catalog",
        "operations": [
          {
            "id": "op1",
            "type": "filter",
            "config": {
              "operation": "and",
              "filters": [
                {"id": "f1", "field": "difficulty", "condition": "greater_than", "value": 5},
                {"id": "f2", "field": "pages", "condition": "less_than", "value": 600}
              ]
            }
          },
          {
            "id": "op2",
            "type": "map",
            "config": {
              "keepOriginalFields": False,
              "mappings": [
                {"id": "m1", "field": "title", "transformation": "uppercase", "renameTo": "title"},
                {"id": "m2", "field": "author", "transformation": "copy", "renameTo": "author"}
              ]
            }
          }
        ]
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The transformed data result",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {"label": "End"},
      "inputs": {},
      "outputs": {
        "readingList": {
          "source": "=js:$vars.transformChain.output"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-to-transform",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "transformChain",
      "targetPort": "input"
    },
    {
      "id": "edge-transform-to-end",
      "sourceNodeId": "transformChain",
      "sourcePort": "output",
      "targetNodeId": "end",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start workflow manually",
      "tags": ["trigger", "start", "manual"],
      "sortOrder": 40,
      "display": {"label": "Manual trigger", "icon": "play", "shape": "circle"},
      "handleConfiguration": [
        {
          "position": "right",
          "handles": [
            {
              "id": "output",
              "type": "source",
              "handleType": "output",
              "showButton": True,
              "constraints": {"forbiddenTargetCategories": ["trigger"]}
            }
          ],
          "visible": True
        }
      ],
      "model": {"type": "bpmn:StartEvent", "entryPointId": True},
      "outputDefinition": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      },
      "toolbarExtensions": {
        "design": {
          "actions": [
            {"id": "change-trigger-type", "icon": "square-mouse-pointer", "label": "Change trigger type"}
          ]
        }
      }
    },
    tr_def,
    end_def
  ],
  "variables": {
    "globals": [
      {
        "id": "catalog",
        "direction": "inout",
        "type": "array",
        "subType": "object",
        "defaultValue": catalog,
        "description": "Catalog of math and data science books"
      },
      {
        "id": "readingList",
        "direction": "out",
        "type": "array",
        "subType": "object",
        "description": "Curated reading list: difficulty > 5 AND pages < 600, title uppercased"
      }
    ],
    "nodes": [
      {
        "nodeId": "transformChain",
        "output": {
          "type": "object",
          "description": "The transformed data result"
        }
      }
    ],
    "variableUpdates": {}
  },
  "layout": {
    "nodes": {
      "start": {"position": {"x": 256, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
      "transformChain": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
      "end": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
    }
  }
}

out_path = '/work/output/artifacts/skill-flow-reading-list/ReadingList/ReadingList/ReadingList.flow'
json.dump(flow, open(out_path, 'w'), indent=2)
print('Written', out_path)
PYEOF

